@pytest.mark.parametrize("stream", [False, True])
def test_opencode_title_interleaving_preserves_permission_state(scripted_http_provider, stream):
    provider, connection = scripted_http_provider
    provider.outside = "/fixture/external"
    provider.reset("permission")
    def post(body):
        connection.request("POST", "/v1/chat/completions", body=json.dumps({**body, "stream": stream}),
                           headers={"Content-Type": "application/json"})
        return read_http_reply(connection)[1]
    title = opencode_title_body()
    assert b"Actor wire fixture" in post(title)
    assert not provider.tool_sent and not provider.tool_returned and provider.failure is None
    post({"tools": [{"type": "function", "function": {"name": "read"}}]})
    assert provider.tool_sent and not provider.tool_returned
    post(title)
    assert provider.tool_sent and not provider.tool_returned and provider.failure is None
    post({"messages": [{"role": "tool", "tool_call_id": "call_wire",
                         "content": "native-shaped unit fixture: permission denied"}]})
    assert provider.tool_returned and provider.failure is None
    post(title)
    assert provider.tool_returned
    provider.failure = "prior failure"
    post(title)
    assert provider.failure == "prior failure"


