@pytest.mark.parametrize("matches", [True, False])
def test_actual_claude_plan_refusal_requires_emitted_target(matches):
    body = json.loads(json.dumps(CLAUDE_R10_PLAN_BODY))
    target = next(part["input"]["file_path"] for msg in body["messages"]
                  for part in (msg["content"] if isinstance(msg["content"], list) else [])
                  if part.get("type") == "tool_use" and part.get("id") == "call_wire")
    records = [{"body": {}}, {"body": body}]
    if matches:
        receipt = wire.require_native_denial(records, "claude", expected_target=target)
        assert receipt["result_texts"] == [f"Cannot write to {target} while in plan mode."]
    else:
        with pytest.raises(AssertionError, match="unrecognized native permission refusal"):
            wire.require_native_denial(records, "claude", expected_target=target+"-unrelated")


def test_matrix_visits_all_fifteen_after_one_expected_failure_and_never_writes_pass(tmp_path, monkeypatch):
    seats = [seat(output_limit=40000+i) for i in range(15)]
    request = gate.request(seats)
    visited = []
    failed = gate.digest(request["seats"][2])
    def native_shape_fixture(row, evidence_dir):
        key = gate.digest(row)
        visited.append(key)
        if key == failed:
            raise AssertionError("one synthetic clean fixture failure")
        return evidence(gate.request([row]))[key]
    output, captures = tmp_path/"pass.json", tmp_path/"native"
    monkeypatch.setattr(wire, "matrix_seats", lambda: seats)
    monkeypatch.setattr(wire, "run_seat", native_shape_fixture)
    monkeypatch.setattr(sys, "argv", ["actor_wire_test", "--matrix", "--record", str(output),
                                     "--evidence-dir", str(captures)])
    with pytest.raises(SystemExit) as raised:
        wire.main()
    assert raised.value.code == 1
    assert visited == [gate.digest(r) for r in request["seats"]]
    assert len(set(visited)) == 15 and not output.exists()
    summary = json.loads((captures/"matrix-results.json").read_text())
    assert summary["status"] == "FAIL" and summary["attempted"] == summary["expected"] == 15
    assert summary["unvisited"] == [] and summary["abort"] is None
    assert [r["seat"] for r in summary["outcomes"] if r["status"] == "FAIL"] == [failed]

